const ARTIFACT_PATH = /^[a-z0-9][a-z0-9_-]*\/[A-Za-z0-9][A-Za-z0-9._-]*$/u;
const ARTIFACT_NAMES = new Set([
  'README.md',
  'OFFICIAL_SOURCE_RESEARCH.md',
  'protocol.v1.json',
  'result.v1.json',
  'freeze.v1.json',
  'development.v1.json',
  'development-result.v1.json',
  'gen_freeze.v1.json',
  'gen_result.v1.json',
]);
const artifactFamilies = new Set<string>();
const artifactPaths = new Set<string>();
let artifactBytes = 0;
for (const artifact of RESEARCH_LAB_ARTIFACTS) {
  if (
    !ARTIFACT_PATH.test(artifact.path)
    || artifact.path !== `${artifact.family}/${artifact.name}`
    || !ARTIFACT_NAMES.has(artifact.name)
  ) {
    throw new TypeError('RESEARCH_LAB_ARTIFACT_PATH_INTEGRITY_INVALID');
  }
  if (artifactPaths.has(artifact.path) || !/^[0-9a-f]{64}$/u.test(artifact.sha256) || !Number.isSafeInteger(artifact.bytes) || artifact.bytes <= 0) {
    throw new TypeError('RESEARCH_LAB_ARTIFACT_RECORD_INTEGRITY_INVALID');
  }
  artifactFamilies.add(artifact.family);
  artifactPaths.add(artifact.path);
  artifactBytes += artifact.bytes;
}
if (
  artifactFamilies.size !== RESEARCH_LAB_ARTIFACT_PROVENANCE.expectedFamilies
  || artifactPaths.size !== RESEARCH_LAB_ARTIFACT_PROVENANCE.expectedFiles
  || artifactBytes !== RESEARCH_LAB_ARTIFACT_PROVENANCE.expectedBytes
) {
  throw new TypeError('RESEARCH_LAB_ARTIFACT_BUNDLE_INTEGRITY_INVALID');
}

const artifactsByFamily = new Map<string, readonly ResearchLabArtifact[]>();
for (const family of artifactFamilies) {
  artifactsByFamily.set(family, Object.freeze(RESEARCH_LAB_ARTIFACTS.filter((artifact) => artifact.family === family)));
}

export function researchLabArtifactsForFamily(family: string): readonly ResearchLabArtifact[] {
  return artifactsByFamily.get(family) ?? Object.freeze([]);
}

export function researchLabArtifactUrl(artifact: ResearchLabArtifact): string {
  return `${RESEARCH_LAB_ARTIFACT_PROVENANCE.publicRoot}/${artifact.path.split('/').map(encodeURIComponent).join('/')}`;
}
